import{_ as a}from"./chunks/daily-2026-08-11-durable-event-identity-terminal-evidence-figure.D90658L1.js";import{_ as n,C as i,o as r,c as o,E as d,a2 as c}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"Agent 运行需要持久身份与显式终态证据","description":"","frontmatter":{"title":"Agent 运行需要持久身份与显式终态证据","date":"2026-08-11","column":"open-source-engineering","category":"daily","summary":"逻辑发生身份应在进入异步边界前创建并跨重试复用，同一逻辑执行还需要显式成功/失败终态证据完成闭合。去重身份能提升对账能力，但不能直接证明端到端 exactly-once 或无损交付。","sources":["research/analysis/Q-20260811-03-event-identity-terminal-evidence.md","research/reading/Q-20260811-03-durable-event-identity-terminal-evidence.md"],"item_id":"Q-20260811-03","lifecycle":"Published","source_research_object":"research/analysis/Q-20260811-03-event-identity-terminal-evidence.md","source_reading_result":"research/reading/Q-20260811-03-durable-event-identity-terminal-evidence.md","cover":"/assets/covers/daily-2026-08-11-durable-event-identity-terminal-evidence.webp","visualization":"/assets/covers/daily-2026-08-11-durable-event-identity-terminal-evidence-figure.svg","visualization_decision":"Required — 独立身份/终态编辑性题图 + 独立重试与终态证据解释图","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"zh/engineering/2026-08-11-durable-event-identity-terminal-evidence.md","filePath":"zh/engineering/2026-08-11-durable-event-identity-terminal-evidence.md","lastUpdated":1786455324000}'),l={name:"zh/engineering/2026-08-11-durable-event-identity-terminal-evidence.md"};function s(u,e,m,h,p,y){const t=i("ArticleCover");return r(),o("div",null,[d(t,{image:"/assets/covers/daily-2026-08-11-durable-event-identity-terminal-evidence.webp",kicker:"开源工程 · 每日研究",title:"Agent 运行需要持久身份与显式终态证据",summary:"逻辑发生身份应在进入异步边界前创建并跨重试复用，同一逻辑执行还需要显式成功/失败终态证据完成闭合。去重身份能提升对账能力，但不能直接证明端到端 exactly-once 或无损交付。",version:"Q-20260811-03",status:"Daily Runtime V5 · 2026-08-11",languageHref:"/en/engineering/2026-08-11-durable-event-identity-terminal-evidence",languageLabel:"English"}),e[0]||(e[0]=c('<h1 id="agent-运行需要持久身份与显式终态证据" tabindex="-1">Agent 运行需要持久身份与显式终态证据 <a class="header-anchor" href="#agent-运行需要持久身份与显式终态证据" aria-label="Permalink to &quot;Agent 运行需要持久身份与显式终态证据&quot;">​</a></h1><p>分布式 Agent 系统经常把三件不同的事情混在一起：“这次逻辑发生有唯一身份”“传输层没有重复写入”“业务动作只执行一次”。三者并不等价。持久 Occurrence ID 首先是一种<strong>对账原语</strong>；真正关闭一次逻辑执行，还需要明确的终态证据。</p><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>Google ADK 的一项已合并 Analytics 改动，在异步交付之前创建稳定 <code>event_id</code>，并在重试时继续复用同一个 ID；同时引入可选的 Committed Stream + Explicit Offset 模式，并增加 Final LLM Response 与 Workflow Node 的显式成功/失败终态元数据。</p><p>同一实现也清楚暴露了保证边界：默认路径仍可能产生重复物理行；Committed Stream 在 Retry Exhaustion、Offset Conflict 或 Stream Rotation Failure 时仍可能丢行；实现中展示的 Offset / Desynchronization State 是进程内状态，没有证明跨重启持久恢复。</p><p>Research Center 的判断因此必须保持精确：<strong>在进入异步边界之前分配持久逻辑身份，在所有重试中复用它，并为同一逻辑执行写入 Typed Terminal Evidence。只有真正拥有端到端保证的层，才有资格使用 exactly-once 这样的表述。</strong></p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>主要一手证据是 Google ADK 已合并实现 Commit <code>04b8b72709f6d17b503cf674c8ac1b89798f655e</code>：</p><ul><li><a href="https://github.com/google/adk-python/commit/04b8b72709f6d17b503cf674c8ac1b89798f655e" target="_blank" rel="noreferrer">https://github.com/google/adk-python/commit/04b8b72709f6d17b503cf674c8ac1b89798f655e</a></li></ul><p>同日 Reading Result 已记录 Writer State Machine、重试复用、Offset Conflict、Drop Boundary、Final-only LLM Termination Metadata，以及 <code>NODE_OUTPUT</code> / <code>NODE_ERROR</code> 的显式终态证据。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>实现会在 Analytics Row 创建时分配 <code>event_id</code>，时间点早于异步写入。由于 Retry 会重发同一 Row，逻辑 Occurrence Identity 能跨越模糊传输重试保持不变。默认模式并不阻止重复物理行，而是让下游可以识别这些行属于同一个逻辑发生并进行 Query-time Deduplication。</p><p>可选 Committed Stream 模式进一步引入 Explicit Offset 和本地冲突处理。模糊发送之后遇到同 Offset 的 <code>AlreadyExists</code> 可以被解释为此前写入已提交；如果本地没有模糊发送却发现 Offset 被占用，则 Stream 被标记为 Desynchronized，并进入 Rotation / Drop Accounting。实现明确选择“有界失败 + 显式丢失边界”，而不是宣称系统无损。</p><p>终态证据也更明确。Final LLM Finish Metadata 只出现在最终 Response Row 上，Workflow Node 则可以产生带 Run / Node Identity 的 <code>NODE_OUTPUT</code> 和 <code>NODE_ERROR</code>。这样 Progressive Telemetry 与 Terminal Outcome 成为两类不同证据。</p><p><img src="'+a+'" alt="持久身份与终态证据解释图"></p><p><em>图 1：逻辑身份在异步交接前创建并跨重试复用，显式成功或失败终态证据关闭同一逻辑执行。来源：Research Center 基于文中引用的一手资料综合绘制。</em></p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>改善了什么</th><th>仍然没有证明什么</th><th>证据类型</th></tr></thead><tbody><tr><td>Enqueue 前创建稳定 <code>event_id</code></td><td>Retry / Duplicate 对账</td><td>Storage-level exactly-once</td><td>已合并实现 + 测试</td></tr><tr><td>Retry 复用同一 ID</td><td>逻辑发生连续性</td><td>外部副作用幂等</td><td>已合并实现 + 测试</td></tr><tr><td>Committed Stream + Offset</td><td>缩小单一 Live Writer 内的模糊重复风险</td><td>Restart-safe、Lossless Delivery</td><td>已合并实现；明确暴露丢失边界</td></tr><tr><td>Typed Terminal Event</td><td>可查询的成功/失败闭合证据</td><td>每个业务结果都语义完整</td><td>已合并实现 + 测试</td></tr><tr><td>Drop / Conflict Counter</td><td>把模糊性变成可观察证据</td><td>自动完成业务恢复</td><td>实现事实 + Research Center 分析</td></tr></tbody></table><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>Identity 与 Guarantee Scope 必须分开。唯一 Event ID 不能阻止下游 Sink 接收到两份物理副本，它只能让消费者知道这两份副本代表同一次逻辑发生。同样，Analytics Transport 的去重也不能证明外部 Tool Call 或 Business Transaction 只执行一次。</p><p>这对 Runtime Governance 非常关键。如果一个任务因为 Timeout 被 Retry，重试应该继续保留原来的 Logical Occurrence ID，同时产生新的 Physical Delivery Attempt Evidence。最终 Terminal Event 再用同一个 Occurrence ID 明确写出 Success、Failure、Cancellation 或 Externally Handed-off Outcome。</p><p>“没有看到错误”也不是终态证据。如果冲突恢复可能主动丢行，Runtime 需要同时保留 Positive Terminal Evidence 和 Ambiguity / Drop Counter。静默日志不能被解释成“什么都没有失败”。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对于数字员工，应在 Work Item、Tool Call 或 Connector Action 进入异步 Queue / External Boundary 之前创建一个持久 Occurrence ID，并在所有 Retry / Recovery 路径中保持不变。Worker / Task Success、Failure、Cancellation 和 External Handoff 都应该有显式终态事件，而不能从日志静默推断完成。</p><p>对于 CodeFlowMu，Runtime Timeline、Report 和 Evidence Record 应引入稳定 Event ID，但必须继续区分 Logical Occurrence Identity 与 Physical Delivery Identity。Duplicate、Retry-exhausted、Offset-conflict 和 Dropped-event Counter 都应作为治理证据长期保留，即使后续 Recovery 成功。</p><p>对于 TMPA，这项实现是 Append-only Provenance 和 Explicit Terminal-state Semantics 的有效研究证据，但单一 Analytics Plugin 不足以支持端到端 exactly-once 的协议级结论。</p><h2 id="边界与不确定性" tabindex="-1">边界与不确定性 <a class="header-anchor" href="#边界与不确定性" aria-label="Permalink to &quot;边界与不确定性&quot;">​</a></h2><p>该实现明确没有证明所有故障下无损交付，也没有证明进程重启后 Durable Offset Reconstruction。Analytics <code>event_id</code> 标识的是 Analytics Occurrence，不是任意外部商业动作。<code>NODE_OUTPUT</code> / <code>NODE_ERROR</code> 能改善可观察性，但仍不能保证每一种 Workflow Node 都产生语义完整的业务结果。</p><h2 id="后续研究" tabindex="-1">后续研究 <a class="header-anchor" href="#后续研究" aria-label="Permalink to &quot;后续研究&quot;">​</a></h2><p>Agent Runtime 需要定义一套 Identity Hierarchy，把 Runtime Task、Worker Claim、Tool/Action Attempt 和 Evidence Event 关联起来而不混为同一种 ID。Restart Recovery 还需要明确 Durable Occurrence Identity 如何与本地 Offset / Retry State 对账；运维策略也应规定 Duplicate / Conflict / Drop Counter 达到什么阈值时必须触发 Alert、Quarantine 或 Governed Re-execution。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>题图位于文章头部，以同一身份标记穿越扰动并进入终态证据舱表现持久身份与闭合；嵌入“观察”部分的解释图说明 Identity Creation、Retry Reuse、Terminal Success/Error 与后续 Reconciliation。两张图均为 Research Center 原创，不包含人为制造的量化数据。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li>Google，<code>adk-python</code>，已合并 Analytics 实现 Commit <code>04b8b72709f6d17b503cf674c8ac1b89798f655e</code>：<a href="https://github.com/google/adk-python/commit/04b8b72709f6d17b503cf674c8ac1b89798f655e" target="_blank" rel="noreferrer">https://github.com/google/adk-python/commit/04b8b72709f6d17b503cf674c8ac1b89798f655e</a></li><li>Research Center Research Object：<code>research/analysis/Q-20260811-03-event-identity-terminal-evidence.md</code></li><li>Research Center Reading Result：<code>research/reading/Q-20260811-03-durable-event-identity-terminal-evidence.md</code></li></ol><blockquote><p>发布状态：已通过 Publication 门禁并正式发布；正文内容未对 Production Candidate 进行实质性改写。</p></blockquote>',35))])}const g=n(l,[["render",s]]);export{v as __pageData,g as default};
